try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&Array.isArray(saved.library)&&saved.doc&&typeof saved.doc.name==='string'&&Array.isArray(saved.doc.steps)&&saved.doc.inputs){doc=saved.doc;library=saved.library;positions=saved.positions||positions;buffer=saved.buffer||JSON.stringify(doc,null,2);origin=saved.origin==='bakery'?'bakery':'organization';workflows=saved.workflows||{};aiMode=saved.aiMode==='auto'?'auto':'ask';activeWorkflow=saved.activeWorkflow||'delivery';datasets=saved.datasets||[];datasetId=datasets.some(d=>d.id===saved.datasetId)?saved.datasetId:'example';}}catch{storageError=true;}
