function expandFileAncestors(path){const parts=path.split('/');for(let i=1;i<parts.length;i++)collapsedFolders.delete(skillSelected.revision+':'+parts.slice(0,i).join('/'));}
function normalizeSkill(k){
 k.skillId=skillId(k);
 const packaged=skillLibrary.find(seed=>seed.revision===k.revision)?.files;
 if(k.scope==='global'&&packaged)k.files=structuredClone(packaged);
 else if(!Array.isArray(k.files))k.files=packaged?structuredClone(packaged):[{path:'SKILL.md',language:'markdown',content:k.instructions||'',executable:false}];
 if(k.draftInstructions&&!Array.isArray(k.draftFiles))k.draftFiles=k.files.map(file=>file.path==='SKILL.md'?{...file,content:k.draftInstructions}:structuredClone(file));
 return k;
}
library.forEach(normalizeSkill);
const savedConversation=workflows[activeWorkflow]?.assistant;if(savedConversation&&origin==='organization'){chat=savedConversation.chat||[];chatDraft=savedConversation.draft||'';aiCheckpoint=savedConversation.checkpoint||null;proposal=savedConversation.proposal||null;selected=savedConversation.selected==='trigger'||doc.steps.some(s=>s.id===savedConversation.selected)?savedConversation.selected:null;}
const savedRecord=workflows[activeWorkflow];if(origin==='organization'){history=savedRecord?.history||[];revision=savedRecord?.revision||0;published=!!savedRecord?.published;lastValid=savedRecord?.lastValid||null;}
