function builtinWorkflow(name){const next=structuredClone(demoWorkflow);next.name=name;next.steps=name==='Research'?next.steps.slice(0,1):name==='Plan'?next.steps.slice(0,2):next.steps;return next;}
function openWorkflow(id,builtin){clearTimeout(renderSource.timer);keepWorkflow();if(builtin){doc=builtinWorkflow(builtin);buffer=JSON.stringify(doc,null,2);positions=structuredClone(defaultPositions);origin='bakery';published=false;}else{const record=workflows[id];if(!record)return;activeWorkflow=id;({doc,buffer,positions,published}=structuredClone(record));origin='organization';}const conversation=builtin?null:workflows[id]?.assistant;chat=conversation?.chat||[];chatDraft=conversation?.draft||'';aiCheckpoint=conversation?.checkpoint||null;aiOpen=false;history=builtin?[]:structuredClone(workflows[id]?.history||[]);revision=builtin?0:workflows[id]?.revision||0;proposal=conversation?.proposal||null;lastValid=builtin?null:workflows[id]?.lastValid||null;selected=conversation?.selected==='trigger'||doc.steps.some(s=>s.id===conversation?.selected)?conversation.selected:null;panel=null;picker=false;tab='editor';runOpen=false;view=small.matches?'outline':'canvas';renderEditor.fitted=false;save();navigate('editor');}
function createWorkflow(next,message,layout=defaultPositions){keepWorkflow();const id=crypto.randomUUID();workflows[id]={doc:structuredClone(next),buffer:JSON.stringify(next,null,2),positions:structuredClone(layout),published:false};openWorkflow(id);notify(message);}

