const stepIcon=s=>s?.repeat?'loop':s?.uses==='rpi.research'?'search':s?.uses==='rpi.plan'?'plan':s?.uses?.startsWith('harness.')?'agent':s?.uses?.startsWith('quality.')?'check':s?.uses==='flow.condition'?'branch':s?.uses==='flow.wait'?'clock':s?.uses==='review.independent'?'shield':'agent';
