function notify(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,5000);}
function save(){if(!validate(doc,library).length)lastValid=structuredClone(doc);keepWorkflow();try{localStorage.setItem(storageKey,JSON.stringify({doc,buffer,library,positions,origin,workflows,activeWorkflow,datasets,datasetId,aiMode}));storageError=false;}catch{storageError=true;}const el=$('save-state');if(el)el.innerHTML=icon(storageError?'flag':'check')+(storageError?'Not saved':'Saved locally');}
function snapshot(){return {at:new Date().toISOString(),doc:structuredClone(doc),buffer,positions:structuredClone(positions),origin,selected,published};}
function checkpoint(){history.push(snapshot());if(history.length>40)history.shift();}
function sourceIsCurrent(){try{return JSON.stringify(parseDocument(buffer))===JSON.stringify(doc);}catch{return false;}}
function pendingSetupError(){const invalid=document.querySelector('[aria-invalid="true"]');if(!invalid)return false;if($('dialog').open)$('dialog').close();invalid.focus();notify('Correct the highlighted value before using this draft. Your edit is retained.');return true;}
function apply(next,message,{replace=false}={}){if(pendingSetupError())return false;if(origin==='bakery'&&!replace){notify('Create an organization copy to customize this Bakery workflow.');return false;}if(!replace&&!sourceIsCurrent()){panel='json';render();notify('Your JSON has unfinished edits. Restore or finish it before changing the canvas.');return false;}checkpoint();doc=next;buffer=JSON.stringify(doc,null,2);revision++;published=false;save();render();if(message)notify(message);return true;}
function issues(){try{return validate(parseDocument(buffer),library);}catch(error){return [{path:'Source',message:error.message}];}}

function focusKey(el=document.activeElement){return el?.id?'#'+CSS.escape(el.id):el?.dataset.act?'[data-act="'+CSS.escape(el.dataset.act)+'"]':el?.dataset.node?'[data-node="'+CSS.escape(el.dataset.node)+'"]':null;}
function focusRoute(){const root=document.querySelector('[data-overlay]')||(route==='editor'?(runOpen?$('run-slot'):$('page-header')):$('page-content'));focusHeading(root)||$('main').focus();}
function focusHeading(root){const heading=root?.querySelector('h1,h2');if(heading){heading.tabIndex=-1;heading.focus();return true;}return false;}
function focusVisible(key,root=document){const el=key&&[...root.querySelectorAll(key)].find(e=>!e.disabled&&!e.closest('[inert]')&&e.checkVisibility({visibilityProperty:true}));el?.focus();return !!el;}
const focusables='button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary,[tabindex="0"]';
function syncAccessibility(){
 document.querySelectorAll('[inert]').forEach(e=>e.inert=false);
 const rail=document.querySelector('.app-rail');rail.classList.toggle('open',drawerOpen);$('nav-backdrop').hidden=!drawerOpen;
 let next=drawerOpen?rail:small.matches?(picker?document.querySelector('.node-picker'):panel?$('panel-slot')?.firstElementChild:aiOpen?$('chat-slot')?.firstElementChild:runOpen?document.querySelector('.run-drawer'):null):null;
 const key=next===rail?'navigation':next?.getAttribute('aria-label')||next?.className||null;
 document.querySelectorAll('[data-overlay]').forEach(e=>{e.removeAttribute('role');e.removeAttribute('aria-modal');delete e.dataset.overlay;});
 if(next){
   if(!overlay)overlayReturn=focusKey();
   next.dataset.overlay='true';next.setAttribute('role','dialog');next.setAttribute('aria-modal','true');
   for(let child=next;child.parentElement&&child.parentElement!==document.documentElement;child=child.parentElement)
     [...child.parentElement.children].forEach(sibling=>{if(sibling!==child&&!['dialog','toast'].includes(sibling.id)&&!(drawerOpen&&sibling.id==='nav-backdrop'))sibling.inert=true;});
   if(!next.contains(document.activeElement))focusVisible(focusables,next);
 }else if(overlay){focusVisible(overlayReturn)||focusVisible('[data-act="menu"]')||$('main').focus();overlayReturn=null;}
 overlay=key;
}
