function fieldChange(input,next,path,message){
 const error=validate(next,library).find(e=>e.path===path);
 const old=$(input.id+'-error');old?.remove();
 if(error){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',input.id+'-error');const note=document.createElement('small');note.id=input.id+'-error';note.className='danger';note.setAttribute('role','alert');note.textContent=error.message;input.after(note);return;}
 input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby');apply(next,message);
}
function routeHash(){
 if(route==='library'){const params=new URLSearchParams();if(workflowSource!=='all')params.set('source',workflowSource);if(workflowState!=='all')params.set('status',workflowState);if(workflowSearch)params.set('q',workflowSearch);if(workflowSort!=='name-asc')params.set('sort',workflowSort);return '#workflows'+(params.size?'?'+params:'');}
 if(route==='skills')return '#skills?scope='+encodeURIComponent(scope);
 const params=new URLSearchParams({view:route==='skill'?skillTab:tab});
 if(route==='skill'&&skillTab==='files'&&skillFile)params.set('file',skillFile);
 if((route==='skill'&&['cases','evaluations'].includes(skillTab))||tab==='evaluations'){
  params.set('dataset',datasetId);params.set('filter',evalFilter);params.set('baseline',String(compareBaseline));if(evalSelected)params.set('case',evalSelected);
 }
 return (route==='skill'?'#skills/'+encodeURIComponent(skillSelected.revision):'#workflows/'+(origin==='bakery'?'bakery/'+encodeURIComponent(doc.name):encodeURIComponent(activeWorkflow)))+'?'+params;
}
function syncRoute(){if(!readingRoute){const hash=routeHash();if(location.hash!==hash)window.history.pushState(null,'',hash);}}
function readRoute(){
 readingRoute=true;
 try{
  const [path,query]=splitRouteHash(location.hash.slice(1)),parts=path.split('/').map(decodeURIComponent),params=new URLSearchParams(query);
  if(parts[0]==='skills'){
   if(parts[1]&&library.some(k=>k.revision===parts[1])){openSkill(parts[1]);skillTab=['files','instructions','cases','evaluations','versions'].includes(params.get('view'))?(params.get('view')==='instructions'?'files':params.get('view')):'files';const requested=params.get('file');if(requested&&editingFiles.some(file=>file.path===requested)){skillFile=requested;expandFileAncestors(requested);}}
   else{route='skills';scope=['global','organization','user'].includes(params.get('scope'))?params.get('scope'):'all';}
  }else if(['workflows','library'].includes(parts[0])){
   if(parts[1]==='bakery'&&['Research','Plan','Implement'].includes(parts[2]))openWorkflow(null,parts[2]);
   else if(parts[1]&&workflows[parts[1]])openWorkflow(parts[1]);
   else{route='library';workflowSource=['organization','bakery'].includes(params.get('source'))?params.get('source'):'all';workflowState=['draft','published','ready'].includes(params.get('status'))?params.get('status'):'all';workflowSearch=(params.get('q')||'').slice(0,120);workflowSort=['name-desc','source'].includes(params.get('sort'))?params.get('sort'):'name-asc';}
   tab=['editor','runs','evaluations'].includes(params.get('view'))?params.get('view'):'editor';runOpen=tab==='runs';
  }
  datasetId=datasets.some(d=>d.id===params.get('dataset'))?params.get('dataset'):'example';
  evalFilter=['Passed','Failed','Error','Not scored'].includes(params.get('filter'))?params.get('filter'):'all';
  evalSelected=currentCases().some(c=>c.id===params.get('case'))?params.get('case'):null;compareBaseline=params.get('baseline')!=='false';
  drawerOpen=false;render();focusRoute();
 }finally{readingRoute=false;}
 if(!location.hash)window.history.replaceState(null,'',routeHash());
}

