function renderNavigation(){const isSkills=route==='skills'||route==='skill',items=[['Work','file','unavailable',false],['Applications','split','unavailable',false],['Sessions','history','unavailable',false],['Machines','agent','unavailable',false],['Integrations','branch','unavailable',false],['Workflows','flow','workflows',!isSkills],['Skills','book','skills',isSkills],['Automations','clock','unavailable',false],['Settings','plan','unavailable',false]];$('navigation').innerHTML=items.map(([name,ico,action,active])=>btn(`<span>${name}</span>`,action,ico,active?'active':'',`aria-label="${name}" title="${name}"${active?' aria-current="page"':''}`)).join('');}
