function edges(){const parts=[];const entry=doc.steps[0];if(entry){const b=point(entry,0),a=positions.trigger||{x:60,y:240};parts.push(curve(a.x+72,a.y+36,b.x,b.y+36));}doc.steps.forEach((s,i)=>{const b=point(s,i);(s.needs||[]).forEach(id=>{const idx=doc.steps.findIndex(n=>n.id===id);if(idx<0)return;const source=doc.steps[idx],a=point(source,idx);const value=Object.values(s.with||{}).find(v=>typeof v==='string'&&v.startsWith('$step.'+id+'.'));const out=value?.split('.')[2];const outs=Object.keys(actions[source.uses]?.outputs||{});const offset=outs.length>1?(outs.indexOf(out)===1?52:22):36;parts.push(curve(a.x+width(source),a.y+offset,b.x,b.y+36));});});const last=doc.steps.at(-1);if(last){const p=point(last,doc.steps.length-1);parts.push(curve(p.x+width(last),p.y+36,p.x+width(last)+44,p.y+36,false));}$('edges').innerHTML=`<defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7" fill="var(--wire)"/></marker></defs>${parts.join('')}`;}
function curve(x,y,a,b,arrow=true){const d=Math.max(35,Math.abs(a-x)*.48);return `<path d="M${x} ${y} C${x+d} ${y},${a-d} ${b},${a} ${b}" fill="none" stroke="var(--wire)" stroke-width="1.5" ${arrow?'marker-end="url(#arrow)"':''}/>`;}
function transform(){if(!$('scene'))return;$('scene').style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;if($('zoom-value'))$('zoom-value').textContent=Math.round(zoom*100)+'%';}
