function bindNodes(){document.querySelectorAll('[data-node]').forEach(el=>{const id=el.dataset.node;el.addEventListener('keydown',e=>{if(e.target!==el)return;if(e.key==='Enter'){selectStep(id);return;}const dirs={ArrowUp:[0,-16],ArrowDown:[0,16],ArrowLeft:[-16,0],ArrowRight:[16,0]};if(dirs[e.key]){e.preventDefault();if(origin==='bakery'){notify('Create a copy before editing this workflow.');return;}checkpoint();const s=doc.steps.find(s=>s.id===id),p=id==='trigger'?positions.trigger:point(s,doc.steps.indexOf(s));positions[id]={x:Math.max(0,p.x+dirs[e.key][0]),y:Math.max(0,p.y+dirs[e.key][1])};renderGraph();document.querySelector(`[data-node="${id}"]`)?.focus();save();}});el.addEventListener('pointerdown',e=>{if(e.target.closest('button,[data-act]')||e.button!==0)return;e.stopPropagation();const start={x:e.clientX,y:e.clientY},s=doc.steps.find(s=>s.id===id),base={...(id==='trigger'?positions.trigger:point(s,doc.steps.indexOf(s)))};let moved=false;el.setPointerCapture(e.pointerId);el.onpointermove=m=>{if(Math.hypot(m.clientX-start.x,m.clientY-start.y)<4&&!moved)return;if(origin==='bakery')return;if(!moved)checkpoint();moved=true;positions[id]={x:Math.max(0,base.x+(m.clientX-start.x)/zoom),y:Math.max(0,base.y+(m.clientY-start.y)/zoom)};el.style.left=positions[id].x+'px';el.style.top=positions[id].y+'px';edges();};el.onpointerup=()=>{el.onpointermove=null;el.onpointerup=null;if(moved)save();else selectStep(id);};});});}
