function freshStep(k,base){let stem=k.title.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/_$/,'')||'skill',id=stem,n=2;while(base.steps.some(s=>s.id===id))id=stem+'_'+n++;const a=actions[k.action];return {id,label:k.title,uses:k.action,skillRevision:k.revision,with:{[a.input]:a.inputType==='string'?'$input.taskId':''},timeout:'30m'};}
