function renderSource(){const focus=focusKey();$('panel-slot').innerHTML=`<section class="panel source-panel" aria-label="Workflow JSON"><div class="panel-head"><h2 class="grow">workflow.json</h2>${btn('Format','format','','quiet')}${iconBtn('Close JSON','close-panel','close')}</div><textarea id="json-source" spellcheck="false" wrap="off" aria-label="Workflow JSON source" ${origin==='bakery'?'readonly':''}>${esc(buffer)}</textarea><div class="source-state" id="source-state" aria-live="polite"></div><div class="panel-footer">${btn('Restore valid','restore','','quiet',lastValid?'':'disabled title="No validated version saved yet"')}${btn('Export JSON','export','','quiet')}</div></section>`;sourceStatus();$('json-source').oninput=e=>{buffer=e.target.value;clearTimeout(renderSource.timer);renderSource.timer=setTimeout(()=>{try{const candidate=parseDocument(buffer);if(!validate(candidate,library).length){history.push({...snapshot(),buffer:JSON.stringify(doc,null,2)});if(history.length>40)history.shift();doc=candidate;revision++;published=false;renderGraph();header();renderChat();}}catch{}sourceStatus();save();},350);};if(selected){const needle='"id": "'+selected+'"',index=buffer.indexOf(needle);if(index>=0){$('json-source').setSelectionRange(index,index+needle.length);$('json-source').scrollTop=Math.max(0,(buffer.slice(0,index).split('\n').length-4)*22);}}syncAccessibility();focusVisible(focus);}
