 slot.innerHTML=`<aside class="panel chat-panel" aria-label="Build with Bakery"><div class="panel-head"><img src="../../../assets/brand/favicon-32.png" width="20" height="20" alt=""><h2 class="grow">Build with Bakery</h2>${iconBtn('Conversation options','chat-options','dots')}${iconBtn('Back to workflow','close-ai','close')}</div><div class="chat-context">${icon('flow')}<span>${esc(doc.name)}</span><span class="badge">${workflowStatus()}</span></div><div class="panel-content" id="chat-transcript" role="log" aria-label="Conversation with Bakery" aria-live="polite">${!chat.length?`<div class="chat-intro"><h2>Let’s build it together.</h2><p>Tell me what should happen. I’ll find the skills and connect the steps.</p></div><div class="prompt-options">${[['Research an issue, then make a plan','research'],['Explain this workflow','explain'],['Add an independent review','review']].map(([label,id])=>btn(label+icon('chevron'),'prompt:'+id,'','prompt-example')).join('')}</div>`:chat.map(m=>`<div class="chat-message ${m.role==='person'?'person-message':''}"><div class="author">${m.role==='person'?'You':icon('agent')+'Bakery'}${stamp(m.at)}</div><p>${esc(m.text)}</p>${m.changes?`<details class="completed-changes"><summary>${count(m.changes.length,'draft change')}</summary>${changeRows(m.changes)}</details>`:''}</div>`).join('')}${proposal?`<section class="proposal-summary" aria-label="Review proposed changes"><div class="row">${icon('flow')}<strong>Review draft changes</strong></div>${changeRows(workflowChanges(doc,proposal.next))}<p class="small">${proposal.base===revision?'Your workflow stays as it is until you apply.':'The draft changed. Refresh to preserve your latest edits.'}</p><div class="row">${btn(proposal.base===revision?'Apply changes':'Refresh proposal',proposal.base===revision?'apply-proposal':'refresh-proposal','','primary',locked?'disabled':'')}${btn('Discard','discard-proposal','','quiet')}</div></section>`:''}${last?.help==='missing-skill'?`<div class="chat-next"><p>No matching skill in this example library.</p>${btn('Create a skill','create-skill-here','plus','quiet')}</div>`:''}${last?.help==='applied'&&!proposal?`<div class="chat-next"><p>Ready for a closer look?</p>${btn('Inspect example output','test','play','quiet')}${btn('Undo last change','undo','undo','quiet',history.length?'':'disabled')}</div>`:''}${aiCheckpoint?`<div class="checkpoint-row">${icon('clock')}<span>Checkpoint · ${count(aiCheckpoint.doc.steps.length,'step')}${stamp(aiCheckpoint.at)}</span>${btn('Compare','compare-checkpoint','','quiet')}</div>`:''}${locked?`<div class="notice">This Bakery workflow is read-only. Make it yours before editing.${btn('Create organization copy','copy-workflow','copy','quiet')}</div>`:''}</div><div class="composer">${selected?`<div class="composer-context"><span>About ${esc(context)}</span>${iconBtn('Clear selected step','clear-context','close')}</div>`:''}<label class="sr-only" for="chat-input">Message Bakery</label><textarea id="chat-input" placeholder="Describe what you’d like to change…" rows="2">${esc(chatDraft)}</textarea><div class="composer-bottom"><label class="sr-only" for="build-mode">Build mode</label><select id="build-mode" aria-describedby="mode-help" ${locked?'disabled':''}><option value="ask" ${aiMode==='ask'?'selected':''}>Ask before editing</option><option value="auto" ${aiMode==='auto'?'selected':''}>Auto-build draft</option></select>${btn('','send-chat','send','primary send',`aria-label="Send message" ${chatDraft.trim()?'':'disabled'}`)}</div></div><p id="mode-help" class="composer-help">${aiMode==='auto'?'Edits this draft. Each change can be undone.':'Review each proposed edit before it is applied.'}</p><p class="prototype-disclosure">Interactive example · no cloud agent connected</p></aside>`;
 $('chat-input').oninput=e=>{chatDraft=e.target.value;slot.querySelector('[data-act=send-chat]').disabled=!chatDraft.trim();save();};$('chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!small.matches){e.preventDefault();sendChat();}};
