function conversationOptions(){modal(`<div class="stack"><h2>Conversation options</h2><p class="muted">Save a point to return to, or begin a fresh conversation for this workflow.</p>${btn('Save checkpoint','save-checkpoint','clock','',origin==='bakery'?'disabled':'')}${btn('Clear conversation','clear-chat','close')}${btn('Close','close-dialog','','quiet')}</div>`);}
