let themeMode=document.documentElement.dataset.appearance||'system';
function applyTheme(){document.documentElement.dataset.theme=themeMode==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):themeMode;document.documentElement.dataset.appearance=themeMode;$('theme').setAttribute('aria-label','Appearance: '+themeMode);}
$('theme').onclick=()=>{modal('<div class="stack"><h2>Appearance</h2><label class="field">Color theme<select id="theme-choice"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label><p class="small">System follows your device appearance.</p>'+btn('Done','close-dialog','','primary')+'</div>');$('theme-choice').value=themeMode;$('theme-choice').onchange=e=>{themeMode=e.target.value;applyTheme();try{localStorage.setItem('bakery-studio-theme',themeMode);}catch{notify('Appearance could not be saved on this device.');}};};
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);applyTheme();
$('dialog').addEventListener('close',()=>{syncAccessibility();if(document.activeElement===document.body||!document.activeElement.checkVisibility({visibilityProperty:true}))focusRoute();});
$('import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>256*1024){notify('This preview accepts JSON files up to 256 KiB.');return;}showImport(file,await file.text());};
