// Native pointer ports support drag-to-connect as well as the keyboard/click input picker.
document.addEventListener('pointerdown',e=>{const port=e.target.closest('.port.output');if(!port||e.button!==0)return;const [,id,output]=port.dataset.act.split(':');const start={x:e.clientX,y:e.clientY};let moved=false;port.setPointerCapture(e.pointerId);const move=m=>{if(Math.hypot(m.clientX-start.x,m.clientY-start.y)<4&&!moved)return;moved=true;const r=$('canvas').getBoundingClientRect();let line=$('pending-wire');if(!line){$('edges').insertAdjacentHTML('beforeend','<path id="pending-wire" fill="none" stroke="var(--accent)" stroke-width="2" stroke-dasharray="5 4"/>');line=$('pending-wire');}const a={x:(start.x-r.left-pan.x)/zoom,y:(start.y-r.top-pan.y)/zoom},b={x:(m.clientX-r.left-pan.x)/zoom,y:(m.clientY-r.top-pan.y)/zoom};line.setAttribute('d',`M${a.x} ${a.y} C${a.x+70} ${a.y},${b.x-70} ${b.y},${b.x} ${b.y}`);};const up=m=>{port.removeEventListener('pointermove',move);port.removeEventListener('pointerup',up);$('pending-wire')?.remove();if(moved){port.addEventListener('click',event=>{event.stopPropagation();event.preventDefault();},{once:true});const target=document.elementFromPoint(m.clientX,m.clientY)?.closest('.port.input');if(target)makeConnection(id,target.dataset.act.slice(7),output);else{wire={id,output};notify('Drop onto a compatible input port, or select that input now.');}}};port.addEventListener('pointermove',move);port.addEventListener('pointerup',up);});
